function testPng(width,height,transparent=true){const crc32=buf=>{let c=0xffffffff;for(const byte of buf){c^=byte;for(let k=0;k<8;k++)c=(c>>>1)^((c&1)?0xedb88320:0);}return (c^0xffffffff)>>>0;};const chunk=(name,data)=>{const n=Buffer.from(name),out=Buffer.alloc(12+data.length);out.writeUInt32BE(data.length,0);n.copy(out,4);data.copy(out,8);out.writeUInt32BE(crc32(out.subarray(4,8+data.length)),8+data.length);return out;};const header=Buffer.alloc(13);header.writeUInt32BE(width,0);header.writeUInt32BE(height,4);header[8]=8;header[9]=6;const stride=width*4,raw=Buffer.alloc((stride+1)*height);if(transparent)raw[4]=255;else for(let y=0;y<height;y++)for(let x=0;x<width;x++)raw[y*(stride+1)+1+x*4+3]=255;return Buffer.concat([Buffer.from([137,80,78,71,13,10,26,10]),chunk('IHDR',header),chunk('IDAT',deflateSync(raw)),chunk('IEND',Buffer.alloc(0))]);}
