const neutral=JSON.parse(readFileSync(new URL('../packs/neutral.json',import.meta.url)));
const fantasy=JSON.parse(readFileSync(new URL('../packs/threshold.json',import.meta.url)));
function harness(p=neutral){let s=createWorld(p,registry,'test');return {get state(){return s;},act(type,args={}){const r=execute(s,{id:`t${s.revision}`,actorId:p.playerId,type,args,expectedRevision:s.revision},p,registry);s=r.state;return r;}};}
function service(p=neutral,provider=new MockProvider()){const store=new Store(),s=createWorld(p,registry,'test');store.insert(s);return {store,service:new GameService(store,{[p.id]:p},registry,provider)};}
const req=(id,revision,type,args={})=>({id,expectedRevision:revision,command:{type,args}});
test('both packs validate, dependency order is resolved',()=>{for(const p of [neutral,fantasy])assert.ok(validatePack(p,registry).length);const mods=resolveModules(neutral,registry).map(m=>m.id);assert.ok(mods.indexOf('social.conversation')<mods.indexOf('social.relationships'));});
test('duplicate IDs and bad references fail with field context',()=>{const p=clone(neutral);p.actors[0].id=p.locations[0].id;assert.throws(()=>validatePack(p,registry),/duplicate/);const q=clone(neutral);q.locations[0].exits[0].to='missing';assert.throws(()=>validatePack(q,registry),/exits: unknown/);});
