test('20 deterministic actions and event replay match',()=>{const a=harness(),b=harness();for(let i=0;i<20;i++){a.act(i%2?'core.wait':'core.inspect');b.act(i%2?'core.wait':'core.inspect');}assert.deepEqual(a.state,b.state);const restored=replay(createWorld(neutral,registry,'test'),a.state.events);for(const k of ['actors','modules','flags','revision','tick','rng'])assert.deepEqual(restored[k],a.state[k]);});
