test('content edits keep an in-progress campaign playable; mechanics edits require a recorded migration',()=>{
 const world=createWorld(neutral,registry,'mech-test');
 const cosmetic=clone(neutral);cosmetic.actors[0].name='Renamed';
 assert.equal(execute(world,{id:'t0',actorId:neutral.playerId,type:'core.wait',args:{},expectedRevision:0},cosmetic,registry).state.tick,1);
 const mechanics=clone(neutral);mechanics.actors.find(a=>a.id==='ada').location='workshop';
 assert.throws(()=>execute(world,{id:'t0',actorId:neutral.playerId,type:'core.wait',args:{},expectedRevision:0},mechanics,registry),/migration required/);
 const changes=describeMechanicsChange(neutral,mechanics);
 assert.ok(changes.includes('actors.ada: changed'));
 const migrated=migratePack(world,neutral,mechanics,registry);
 assert.equal(migrated.packDigest,mechanicsDigest(mechanics));
 assert.deepEqual(migrated.migrations,[{tick:world.tick,from:mechanicsDigest(neutral),to:mechanicsDigest(mechanics),changes}]);
 assert.equal(execute(migrated,{id:'t0',actorId:neutral.playerId,type:'core.wait',args:{},expectedRevision:migrated.revision},mechanics,registry).state.tick,1);
 assert.throws(()=>migratePack(world,neutral,neutral,registry),/No mechanics change/);
});
