test('a failed daypart can retry its prose without replaying mechanical events',async()=>{let down=true;const model={name:'repairable',async generateDaypart(c){if(down)throw Error('Server not ready');return {lines:['You hear the building quiet down.','Work from earlier weighs on you.','Tomorrow brings the open house.'],hangouts:c.hangoutCandidates.map(h=>({char:h.char,text:`Meet me at ${h.where}?`,description:h.plan})),breakups:[],posts:[]};}};const {store,service:svc}=service(living,model);try{const before=await svc.act('test',req('night',0,'world.nextDaypart'));assert.equal(before.turn.failureReason,'Server not ready');const events=JSON.stringify(before.state.events);down=false;const after=await svc.retry('test','night');assert.equal(after.turn.fallback,false);assert.equal(after.state.revision,before.state.revision);assert.equal(JSON.stringify(after.state.events),events);assert.equal(after.turn.sceneLines.length,3);const imported=validateImport(exportCampaign(after.state),living,registry);assert.deepEqual(imported.turns.night.sceneLines,after.turn.sceneLines);await assert.rejects(()=>svc.retry('test','night'),/failed generated turn/);}finally{store.close();}});
