test('scenario studio saves drafts, validates, publishes immutable versions, and reloads them',async()=>{
 const dir=mkdtempSync(join(tmpdir(),'story-studio-'));let app;
 const start=async()=>{app=createApp({dataPath:join(dir,'campaigns.sqlite'),scenarioDir:join(dir,'scenarios')});await new Promise(r=>app.server.listen(0,'127.0.0.1',r));return `http://127.0.0.1:${app.server.address().port}`;};
 const stop=async()=>{await new Promise(r=>app.server.close(r));app.store.close();};
 const post=async(base,path,body)=>{const r=await fetch(base+path,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)});return {status:r.status,data:await r.json()};};
 try{let base=await start();let d=(await post(base,'/api/studio/create',{})).data;d.pack.title='A Created World';d.pack.locations.push({id:'garden',name:'Garden',description:'A quiet garden.',exits:[{to:'start'}]});d.pack.locations[0].exits=[{to:'garden'}];d.pack.actors.push({id:'friend',name:'Friend',location:'garden',traits:['curious']});d.pack.lorebook.push({id:'garden-lore',scope:'location',location:'garden',text:'The garden is old.',knownBy:'public',tags:['garden']});assert.equal((await post(base,'/api/studio/save',d)).status,200);let published=(await post(base,'/api/studio/publish',{id:d.id})).data;assert.match(published.id,/^created\./);let game=(await post(base,'/api/new',{packId:published.id})).data;assert.equal(game.pack.title,'A Created World');assert.equal((await post(base,'/api/action',{campaignId:game.state.campaignId,...req('walk',0,'core.move',{to:'garden'})})).data.state.actors.player.location,'garden');
 d.pack.locations[0].exits=[{to:'missing'}];await post(base,'/api/studio/save',d);assert.equal((await post(base,'/api/studio/publish',{id:d.id})).status,400);await stop();base=await start();assert.equal((await post(base,'/api/load',{id:game.state.campaignId})).data.pack.id,published.id);assert.equal((await (await fetch(base+'/api/studio/list')).json()).drafts[0].id,d.id);await stop();}finally{if(app?.server.listening)await stop();rmSync(dir,{recursive:true,force:true});}
});
