test('local AI settings discover a model, test it, switch narration, and reject nonlocal URLs',async()=>{
 assert.throws(()=>normalizeLocalEndpoint('https://example.com/v1/chat/completions'),/local HTTP/);
 const {createServer}=await import('node:http');const modelServer=createServer(async(req,res)=>{res.setHeader('Content-Type','application/json');if(req.url==='/v1/models')res.end(JSON.stringify({data:[{id:'test-local-model'}]}));else if(req.url==='/v1/chat/completions'){let raw='';for await(const part of req)raw+=part;const request=JSON.parse(raw),messages=request.messages,intent=messages.some(m=>m.content?.includes('"available"')),scene=messages.some(m=>m.content?.includes('"job":"daypart_intro"'));if(scene)assert.equal(request.response_format.type,'json_schema');const content=intent?'{"type":"core.inspect","args":{}}':scene?JSON.stringify({lines:['The lights dim.','The workshop waits.','Tomorrow brings the open house.'],hangouts:[{char:'ada',text:'Meet me?',description:'Review plans'},{char:'brin',text:'See what I made?',description:'Visit workshop'}],breakups:[],posts:[]}):request.response_format?.json_schema?.name==='visual_novel_scene'?JSON.stringify({lines:[{speaker:'',text:'READY'}]}):'READY';res.end(JSON.stringify({choices:[{message:{content}}]}));}else{res.statusCode=404;res.end('{}');}});
 await new Promise(resolve=>modelServer.listen(0,'127.0.0.1',resolve));
 const app=createApp({dataPath:':memory:'});await new Promise(resolve=>app.server.listen(0,'127.0.0.1',resolve));
 try{const base=`http://127.0.0.1:${app.server.address().port}`,endpoint=`http://127.0.0.1:${modelServer.address().port}/v1/chat/completions`;
  const post=async(path,body)=>{const response=await fetch(base+path,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)});return {status:response.status,data:await response.json()};};
  assert.deepEqual((await post('/api/ai/models',{endpoint})).data.models,['test-local-model']);
  assert.equal((await post('/api/ai/test',{endpoint,model:'test-local-model'})).data.reply,'READY');
  const sample=(await post('/api/ai/test-scene',{endpoint,model:'test-local-model'}));assert.equal(sample.status,200,JSON.stringify(sample.data));assert.deepEqual(sample.data.hangouts,['ada','brin']);
  assert.equal((await post('/api/ai/config',{mode:'local',endpoint,model:'test-local-model'})).data.provider,'Configured model');
  const newGame=(await post('/api/new',{packId:neutral.id})).data;
  const turn=(await post('/api/action',{campaignId:newGame.state.campaignId,id:'local-test',expectedRevision:0,command:{type:'core.inspect',args:{}}})).data;
  assert.equal(turn.state.turns['local-test'].narrative,'READY');
  const free=(await post('/api/action',{campaignId:newGame.state.campaignId,id:'local-free-text',expectedRevision:1,input:'Look around'})).data;
  assert.equal(free.state.turns['local-free-text'].command.type,'core.inspect');assert.equal(free.state.turns['local-free-text'].narrative,'READY');
  assert.equal((await post('/api/ai/config',{mode:'offline'})).data.provider,'Offline demo');
  assert.equal((await post('/api/ai/config',{mode:'local',endpoint:'http://example.com:1234/v1/chat/completions',model:'x'})).status,400);
 }finally{await new Promise(resolve=>app.server.close(resolve));app.store.close();await new Promise(resolve=>modelServer.close(resolve));}
});
