test('facts the player states about themselves may quote the player action, but only for the player subject',()=>{const p=clone(neutral);const turn={id:'t1',input:'Tell Ada my name is Mara and I grew up by the harbor',command:{type:'social.speak',args:{target:'ada',text:'my name is Mara'}},events:[]};const narrative='Ada nods and smiles.';assert.equal(validateGeneratedFacts([{subject:p.playerId,text:'The player grew up by the harbor.',quote:'I grew up by the harbor'}],p,turn,narrative).length,1);assert.throws(()=>validateGeneratedFacts([{subject:'ada',text:'Ada grew up by the harbor.',quote:'I grew up by the harbor'}],p,turn,narrative),/quote/);});
test('romance tempo caps gifts and requires an authored rank-up scene',()=>{
 const p=clone(neutral);p.modules['social.dating']='0.1.0';p.modules['story.scenes']='0.1.0';p.modules['social.romance-tempo']='0.1.0';delete p.modules['world.schedule'];for(const id of ['rose','book','cake'])p.items.push({id,name:id,owner:p.playerId});p.datingProfiles=[{character:'ada',initialChemistry:20,initialPhase:'crush',agreements:['monogamous'],thresholds:{crush:10,date:30,exclusive:60},preferences:[],signals:[]}];p.romanceTempoProfiles=[{character:'ada',ranks:[{id:'acquainted',name:'Acquainted',points:0,ceiling:10},{id:'trusted',name:'Trusted',points:10,ceiling:30,scene:'ada-rank-two'}],gifts:{periodTicks:7,limitPerPeriod:2,preferences:[{item:'rose',reaction:'loved',points:10},{item:'book',reaction:'liked',points:6},{item:'cake',reaction:'liked',points:6}]}}];p.scriptedScenes=[{id:'ada-rank-two',title:'A defining conversation',opening:'Ada asks what this bond means.',trigger:{event:'social.romanceRankReady',match:{character:'ada',rank:'trusted'}},choices:[{id:'affirm',label:'Affirm the bond',result:'You understand each other better.',effects:[{type:'romanceRank',character:'ada',to:'trusted'}]}]}];validatePack(p,registry);const h=harness(p);h.act('items.give',{item:'rose',target:'ada'});assert.equal(h.state.modules['social.romance-tempo'].characters.ada.points,10);assert.equal(h.state.modules['social.romance-tempo'].characters.ada.ready,'trusted');assert.equal(h.state.modules['story.scenes'].pending,'ada-rank-two');h.act('story.choose',{scene:'ada-rank-two',choice:'affirm'});assert.equal(h.state.modules['social.romance-tempo'].characters.ada.rank,1);h.act('items.give',{item:'book',target:'ada'});h.act('items.give',{item:'cake',target:'ada'});assert.equal(h.state.modules['social.romance-tempo'].characters.ada.points,16);assert.ok(h.state.events.some(e=>e.type==='social.giftLimitReached'&&e.payload.item==='cake'));assert.deepEqual(replay(createWorld(p,registry,'test'),h.state.events).modules['social.romance-tempo'],h.state.modules['social.romance-tempo']);
});

test('deterministic playtest audits routes without confusing unseen content with broken content',()=>{
 const p=clone(neutral);p.modules['story.scenes']='0.1.0';p.scriptedScenes=[{id:'late-scene',title:'Later',opening:'Later.',trigger:{event:'core.moved',match:{to:'meeting'}},when:{minTick:99},choices:[{id:'leave',label:'Leave',result:'Done.',effects:[]}]}];validatePack(p,registry);const {state,report}=runDeterministicPlaytest(p,registry,{turns:8});assert.equal(report.summary.critical,0);assert.ok(report.findings.some(x=>x.code==='never-fired'&&x.scene==='late-scene'&&x.severity==='info'));const direct=auditWorld(state,p,{turns:8});assert.equal(direct.summary.critical,0);
});

test('creator playtest suite covers every opening with reproducible route summaries',()=>{const p=clone(neutral);p.startOptions=[{id:'early',title:'Early',playerLocation:'hub',tick:0},{id:'late',title:'Late',playerLocation:'hub',tick:5}];const a=runPlaytestSuite(p,registry,{turns:5,seeds:[3,9]}),b=runPlaytestSuite(p,registry,{turns:5,seeds:[3,9]});assert.equal(a.summary.runs,4);assert.deepEqual(a,b);});

test('short romance routes can advance automatically without scripted scenes',()=>{
 const p=clone(neutral);p.modules['social.dating']='0.1.0';p.modules['social.romance-tempo']='0.1.0';delete p.modules['world.schedule'];p.items.push({id:'chocolate',name:'Chocolate',owner:p.playerId});p.datingProfiles=[{character:'ada',initialChemistry:20,initialPhase:'crush',agreements:['casual'],thresholds:{crush:10,date:20,exclusive:60},preferences:[],signals:[]}];p.romanceTempoProfiles=[{character:'ada',advancement:'automatic',ranks:[{id:'spark',name:'Spark',points:0,ceiling:5},{id:'casual',name:'Casual lovers',points:5,ceiling:20}],gifts:{preferences:[{item:'chocolate',reaction:'liked',points:5}]}}];validatePack(p,registry);const h=harness(p),result=h.act('items.give',{item:'chocolate',target:'ada'});assert.equal(h.state.modules['social.romance-tempo'].characters.ada.rank,1);assert.equal(h.state.modules['social.romance-tempo'].characters.ada.ready,null);assert.ok(result.turn.events.some(e=>e.type==='social.romanceRankChanged'&&e.payload.to==='casual'));assert.equal(h.state.modules['story.scenes'],undefined);
});

test('direct intimacy categories complete consensual short encounters without scripted scenes',()=>{
 const p=clone(neutral);p.modules['social.dating']='0.1.0';p.modules['social.intimacy']='0.1.0';delete p.modules['world.schedule'];p.actors.find(x=>x.id==='player').age=24;p.actors.find(x=>x.id==='ada').age=25;p.datingProfiles=[{character:'ada',initialChemistry:25,initialSatisfaction:20,initialPhase:'crush',agreements:['casual'],thresholds:{crush:10,date:30,exclusive:60},preferences:[],signals:[]}];p.intimacySettings={difficulty:'easy',contentLevel:'explicit',privateLocations:['hub'],aftercareOptions:[]};p.intimacyCategories=[{id:'hookup',name:'Casual hookup',casual:true,privacy:'private',resolution:'direct',defaultOutcome:'positive',requiresAgreement:[]}];p.intimacyProfiles=[{character:'ada',openness:90,casual:true,consentPolicy:'threshold',allowedCategories:['hookup'],blockedCategories:[],interests:[]}];validatePack(p,registry);const h=harness(p);h.act('social.requestIntimacy',{character:'ada',category:'hookup'});const result=h.act('social.beginIntimacy',{character:'ada',category:'hookup'});assert.equal(h.state.modules['social.intimacy'].characters.ada.active,null);assert.equal(h.state.modules['social.intimacy'].characters.ada.encounters.length,1);assert.ok(result.turn.events.some(e=>e.type==='social.intimacyStarted'));assert.ok(result.turn.events.some(e=>e.type==='social.intimacyCompleted'));assert.equal(h.state.modules['story.scenes'],undefined);
});

test('phone threads persist unread state, replies, and schedule-checked expiring offers',()=>{
 const p=clone(neutral);p.modules['social.phone']='0.1.0';delete p.modules['world.schedule'];p.phoneContacts=['ada'];p.phoneMessages=[{id:'ada-invite',character:'ada',text:'Want to meet here?',trigger:{event:'core.inspected',match:{location:'hub'}},replies:[{id:'yes',text:'I would like that.'},{id:'later',text:'Maybe later.'}],offer:{location:'hub',expiresIn:2,plan:'Spend time together'}}];validatePack(p,registry);const h=harness(p),look=h.act('core.inspect');assert.ok(look.turn.events.some(e=>e.type==='social.messageReceived'));assert.equal(h.state.modules['social.phone'].threads.ada[0].read,false);assert.equal(contextFor(h.state,p,p.playerId).phone.contacts[0].unread,1);h.act('social.readThread',{character:'ada'});h.act('social.replyMessage',{message:'ada-invite',reply:'yes'});const accepted=h.act('social.acceptPhoneOffer',{message:'ada-invite'});assert.ok(accepted.turn.events.some(e=>e.type==='social.phoneOfferAccepted'));assert.equal(h.state.scene.characters[0],'ada');assert.deepEqual(replay(createWorld(p,registry,'test'),h.state.events).modules['social.phone'],h.state.modules['social.phone']);
 const expired=harness(p);expired.act('core.inspect');for(let i=0;i<3;i++)expired.act('core.wait');assert.equal(expired.state.modules['social.phone'].threads.ada[0].offer.status,'expired');assert.throws(()=>expired.act('social.acceptPhoneOffer',{message:'ada-invite'}),/unavailable|expired/);
});

test('route endings unlock from committed adult relationship state and can only be chosen once',()=>{
 const p=clone(neutral);p.modules['social.dating']='0.1.0';p.modules['social.intimacy']='0.1.0';p.modules['story.endings']='0.1.0';delete p.modules['world.schedule'];p.actors.find(x=>x.id==='player').age=24;p.actors.find(x=>x.id==='ada').age=25;p.datingProfiles=[{character:'ada',initialChemistry:25,initialSatisfaction:20,initialPhase:'crush',agreements:['casual'],thresholds:{crush:10,date:30,exclusive:60},preferences:[],signals:[]}];p.intimacySettings={difficulty:'easy',contentLevel:'explicit',privateLocations:['hub'],aftercareOptions:[]};p.intimacyCategories=[{id:'hookup',name:'Casual hookup',casual:true,privacy:'private',resolution:'direct',requiresAgreement:[]}];p.intimacyProfiles=[{character:'ada',openness:90,casual:true,consentPolicy:'threshold',allowedCategories:['hookup'],blockedCategories:[],interests:[]}];p.endings=[{id:'casual-ending',name:'Keep it casual',character:'ada',text:'You agree to keep seeing each other.',requires:{datingPhases:{ada:'crush'},intimacyCounts:{ada:1}}}];validatePack(p,registry);const h=harness(p);h.act('social.requestIntimacy',{character:'ada',category:'hookup'});const encounter=h.act('social.beginIntimacy',{character:'ada',category:'hookup'});assert.ok(encounter.turn.events.some(e=>e.type==='story.endingUnlocked'));assert.deepEqual(contextFor(h.state,p,p.playerId).unlockedEndings,[{id:'casual-ending',name:'Keep it casual',character:'ada'}]);const chosen=h.act('story.chooseEnding',{ending:'casual-ending'});assert.ok(chosen.turn.events.some(e=>e.type==='story.endingChosen'));assert.throws(()=>h.act('story.chooseEnding',{ending:'casual-ending'}),/already chosen/);
});

test('social feed publishes source-linked posts with persistent unread state and one reaction',()=>{
 const p=clone(neutral);p.modules['social.feed']='0.1.0';p.feedPosts=[{id:'ada-update',author:'ada',text:'The workshop meeting is starting.',trigger:{event:'core.inspected',match:{location:'hub'}},visibility:'contacts',reactions:['like','flirt']}];validatePack(p,registry);const h=harness(p),look=h.act('core.inspect');assert.ok(look.turn.events.some(e=>e.type==='social.feedPostPublished'&&e.payload.post==='ada-update'));assert.equal(h.state.modules['social.feed'].published[0].read,false);assert.equal(contextFor(h.state,p,p.playerId).socialFeed[0].sourceEvent,'core.inspected');h.act('social.readFeed',{});const reaction=h.act('social.reactToPost',{post:'ada-update',reaction:'flirt'});assert.ok(reaction.turn.events.some(e=>e.type==='social.feedReacted'&&e.payload.reaction==='flirt'));assert.equal(h.state.modules['social.feed'].published[0].reaction,'flirt');assert.throws(()=>h.act('social.reactToPost',{post:'ada-update',reaction:'like'}),/already reacted/);assert.deepEqual(replay(createWorld(p,registry,'test'),h.state.events).modules['social.feed'],h.state.modules['social.feed']);
});

test('schedule exceptions override routines and timed events resolve attendance or missed recaps',()=>{
 const p=clone(neutral);p.modules['story.timed-events']='0.1.0';p.scheduleExceptions=[{id:'ada-date',actor:'ada',startTick:1,endTick:2,location:'hub'}];p.timedEvents=[{id:'private-party',name:'Private party',startTick:1,endTick:2,location:'hub',character:'ada',attendedFlag:'party-attended',missedFlag:'party-missed',missedRecap:'Ada went to the party without you.'}];validatePack(p,registry);const attended=harness(p);attended.act('core.wait');assert.equal(attended.state.actors.ada.location,'hub');const done=attended.act('story.attendTimedEvent',{event:'private-party'});assert.ok(done.turn.events.some(e=>e.type==='story.timedEventAttended'));assert.equal(attended.state.flags['party-attended'],true);const missed=harness(p);for(let i=0;i<3;i++)missed.act('core.wait');assert.equal(missed.state.modules['story.timed-events'].status['private-party'],'missed');assert.equal(missed.state.flags['party-missed'],true);assert.ok(missed.state.events.some(e=>e.type==='story.timedEventMissed'&&e.payload.recap.includes('without you')));
});

test('economy supports bounded debt, authored services, and cooldown wages',()=>{
 const p=clone(neutral);p.modules['world.economy']='0.1.0';p.initialMoney=5;p.economySettings={debtLimit:20};p.services=[{id:'room',name:'Rent a private room',location:'hub',price:15,once:true,result:'The room is yours for the evening.'}];p.wageRules=[{id:'shift-pay',event:'core.inspected',match:{location:'hub'},amount:10,cooldown:2}];validatePack(p,registry);const h=harness(p);h.act('world.buyService',{service:'room'});assert.equal(h.state.modules['world.economy'].balance,-10);assert.throws(()=>h.act('world.buyService',{service:'room'}),/already purchased/);h.act('core.inspect');assert.equal(h.state.modules['world.economy'].balance,0);h.act('core.inspect');assert.equal(h.state.modules['world.economy'].balance,0);h.act('core.wait');h.act('core.wait');h.act('core.inspect');assert.equal(h.state.modules['world.economy'].balance,10);
});

test('campus, bar, and fantasy adult templates run the same reusable systems',()=>{
 const files=['template-campus.json','template-bar.json','template-fantasy-town.json'],expected=['social.phone','social.feed','social.dating','social.intimacy','world.economy','story.endings','story.timed-events','world.schedule'];for(const file of files){const p=JSON.parse(readFileSync(new URL(`../packs/${file}`,import.meta.url)));validatePack(p,registry);for(const id of expected)assert.equal(p.modules[id],'0.1.0');const h=harness(p),first=h.act('core.inspect');assert.ok(first.turn.events.some(e=>e.type==='social.messageReceived'));const work=p.wageRules[0].match.location;if(h.state.actors[p.playerId].location!==work)h.act('core.move',{to:work});h.act('core.inspect');assert.equal(h.state.modules['social.phone'].delivered.length,1);assert.equal(h.state.modules['social.feed'].published.length,1);assert.ok(h.state.modules['world.economy'].wages[p.wageRules[0].id]!==undefined);}
});
